document.addEventListener('click',async(e)=>{const b=e.target.closest('[data-action]');if(!b||busy)return;const action=actions[b.dataset.action];if(!action)return;try{busy=true;b.disabled=true;await action(b.dataset.id);}catch(error){toast(error.message||'No se pudo completar la operación.',true);}finally{busy=false;if(b.isConnected)b.disabled=false;}});
document.addEventListener('submit',async(e)=>{e.preventDefault();const form=e.target;if(busy)return;busy=true;const button=form.querySelector('[type="submit"]')||form.querySelector('button:not([type])');if(button)button.disabled=true;try{if(form.id==='login-form'){const fd=new FormData(form);await api.login(fd.get('email'),fd.get('password'));await refresh();location.hash=isAdmin()?'#/dashboard':'#/pos';render();}else if(form.id==='modal-form'&&formHandler){const handler=formHandler;await handler(new FormData(form));if(formHandler===handler)closeModal();}else if(form.id==='settings-form'){const fd=new FormData(form);let logoPath=state.settings.logoPath||null;const file=fd.get('logo');if(file?.size)logoPath=await api.uploadImage(file,'store-logo');await mutate('settings.save',{name:fd.get('name'),currency:fd.get('currency'),timezone:fd.get('timezone'),receiptMessage:fd.get('receiptMessage'),logoPath});toast('Configuración guardada.');}}catch(error){const target=form.id==='login-form'?$('#login-error'):form.id==='modal-form'?$('#form-error'):null;if(target)target.textContent=error.message;else toast(error.message,true);}finally{busy=false;if(button?.isConnected)button.disabled=false;}});
function rerenderFocused(id){const input=$('#'+id),pos=input?.selectionStart;render();const next=$('#'+id);next?.focus();try{next?.setSelectionRange(pos,pos);}catch{}}
document.addEventListener('input',(e)=>{const id=e.target.id;if(id==='pos-search'){search=e.target.value;rerenderFocused(id);}if(id==='product-search'){productSearch=e.target.value;page=1;rerenderFocused(id);}if(e.target.closest('#modal-form')){updatePricePreview();const change=$('#change-preview');if(change){const value=Number($('#f-paymentReceivedCents').value)*100-Number(change.dataset.total);change.textContent=value>=0?`Cambio: ${money(Math.round(value))}`:`Falta: ${money(Math.round(-value))}`;}}});
document.addEventListener('change',(e)=>{const id=e.target.id;if(id==='pos-discount'){discountPercent=Math.max(0,Math.min(99,Math.round(Number(e.target.value)||0)));setTimeout(()=>render(),0);}if(id==='product-category'){productCat=e.target.value;page=1;render();}if(id==='product-supplier'){productSup=e.target.value;page=1;render();}if(id==='report-from'||id==='report-to'){if(id==='report-from')from=e.target.value;else to=e.target.value;if(from&&to&&from>to){toast('La fecha inicial no puede ser posterior a la final.',true);if(id==='report-from')from='';else to='';}page=1;render();}if(id==='f-paymentMethod'&&$('#change-preview')){if(e.target.value!=='cash')$('#f-paymentReceivedCents').value=(Number($('#change-preview').dataset.total)/100).toFixed(2);$('#f-paymentReceivedCents').dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('keydown',e=>{if(e.target.id==='pos-search'&&e.key==='Enter'){e.preventDefault();const p=state.products.find(p=>p.active&&(p.barcode===search.trim()||p.sku===search.trim()));try{if(!p)throw Error('Código no encontrado.');search='';addProduct(p.id);$('#pos-search')?.focus();}catch(error){toast(error.message,true);}}});
window.addEventListener('hashchange',()=>{page=1;if(state)render();});window.addEventListener('offline',()=>toast('Sin conexión. Verifica tu conexión antes de cobrar.',true));
app.innerHTML='<div class="loading">Abriendo MAC Store…</div>';
try { if(await api.restore()){await refresh();render();} else loginScreen(); }
catch(error){loginScreen(error.message);}
